"""A readable page per ontology, generated by `onto gen` like every other artefact.

    ontology/workflow.yaml        -> the page named by `docs` under [workflow]
    ontology/domains/<ctx>.yaml   -> the page named by `docs` under [contexts.<ctx>]

A page is derived from the LinkML source alone: a class diagram, every term
with its definition, the enums and the external mappings. It holds no
timestamps and no instance data, so it changes only when the ontology does and
`onto gen --check` can compare it byte for byte.
"""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path

from .glossary import KIND_ORDER, Glossary, Term


@dataclass(frozen=True)
class Source:
    """What a Glossary reads of a bounded context: the workflow ontology has these too."""

    name: str
    schema: Path


def renderer(name: str, schema: Path) -> Callable[[str, str], str]:
    """A `gen.Target` renderer for the page of one ontology."""

    def render(source: str, notice: str) -> str:
        return page(Glossary(Source(name, schema)), source, notice)

    return render


def page(glossary: Glossary, source: str, notice: str) -> str:
    schema = glossary.view.schema
    terms = sorted(glossary.terms.values(), key=lambda t: (KIND_ORDER[t.kind], t.name))
    parts = [
        f"<!-- {notice} -->",
        f"# {_cell(schema.title or schema.name)}",
        _clean(schema.description),
        f"Source: `{source}`, version {schema.version or 'unversioned'}. "
        f"Namespace: `{glossary.namespace}`.",
        "## Classes and their links",
        f"```mermaid\n{class_diagram(glossary)}\n```",
        "## Terms",
        _table(
            ("Term", "Kind", "Definition", "Classification", "Aliases", "Never write"),
            [
                (
                    f"`{t.name}`",
                    t.kind,
                    t.definition,
                    t.classification,
                    ", ".join(t.aliases),
                    ", ".join(t.denied_synonyms),
                )
                for t in terms
            ],
        ),
        "## Enums",
        *_enums(glossary, terms),
        "## External mappings",
        _mappings(glossary, terms),
    ]
    return "\n\n".join(part for part in parts if part) + "\n"


def class_diagram(glossary: Glossary) -> str:
    """A Mermaid classDiagram: names, ranges and relations only, never free text."""
    view = glossary.view
    classes = view.all_classes(imports=False)
    enums = view.all_enums(imports=False)
    blocks: list[str] = []
    relations: list[str] = []

    for name in sorted(classes):
        cls = classes[name]
        members: list[str] = []
        for slot_name in sorted(view.class_slots(name, direct=True)):
            slot = view.induced_slot(slot_name, name)
            rng = slot.range or view.schema.default_range
            many = bool(slot.multivalued)
            if rng in classes:
                low = "1" if slot.required or slot.identifier else "0"
                target = {("1", True): "1..*", ("0", True): "*", ("1", False): "1"}.get(
                    (low, many), "0..1"
                )
                relations.append(f'    {name} --> "{target}" {rng} : {slot_name}')
            else:
                if rng in enums:
                    relations.append(f"    {name} ..> {rng} : {slot_name}")
                members.append(f"        +{f'List~{rng}~' if many else rng} {slot_name}")
        if cls.abstract or cls.mixin:
            members.insert(0, f"        <<{'mixin' if cls.mixin else 'abstract'}>>")
        blocks.append(_block(name, members))
        if cls.is_a:
            relations.append(f"    {cls.is_a} <|-- {name}")
        relations.extend(f"    {mixin} <|.. {name}" for mixin in sorted(cls.mixins or ()))

    for name in sorted(enums):
        values = [f"        {value}" for value in enums[name].permissible_values]
        blocks.append(_block(name, ["        <<enumeration>>", *values]))

    return "\n".join(["classDiagram", *blocks, *sorted(relations)])


def _block(name: str, members: list[str]) -> str:
    if not members:
        return f"    class {name}"
    return "\n".join([f"    class {name} {{", *members, "    }"])


def _enums(glossary: Glossary, terms: list[Term]) -> list[str]:
    out: list[str] = []
    for enum in (t for t in terms if t.kind == "enum"):
        rows = [
            (f"`{value}`", glossary.terms[f"{enum.name}.{value}"].definition)
            for value in enum.values
        ]
        table = _table(("Value", "Definition"), rows)
        out.append(
            "\n\n".join(part for part in (f"### {enum.name}", enum.definition, table) if part)
        )
    return out or ["None."]


def _mappings(glossary: Glossary, terms: list[Term]) -> str:
    rows: list[tuple[str, str, str]] = []
    for term in terms:
        # A term whose IRI lies outside the ontology's namespace is an external
        # concept reused by reference (class_uri or slot_uri).
        if not term.iri.startswith(glossary.namespace):
            rows.append((f"`{term.name}`", "is", term.iri))
        rows.extend((f"`{term.name}`", "exact", iri) for iri in term.exact_mappings)
        rows.extend((f"`{term.name}`", "close", iri) for iri in term.close_mappings)
    if not rows:
        return "None."
    return _table(("Term", "Mapping", "External concept"), rows)


def _table(header: tuple[str, ...], rows: list[tuple[str, ...]]) -> str:
    lines = [
        "| " + " | ".join(header) + " |",
        "|" + "|".join(" --- " for _ in header) + "|",
        *("| " + " | ".join(_cell(value) for value in row) + " |" for row in rows),
    ]
    return "\n".join(lines)


def _clean(text: str | None) -> str:
    return " ".join((text or "").split())


def _cell(text: str) -> str:
    return _clean(text).replace("|", "\\|")
